// ---- weather ahead: the events are decided by code ---------------------------------------------------------
const nfkc = (s) => String(s ?? '').normalize('NFKC');
const num = (v) => { const n = Number(String(v ?? '').trim()); return String(v ?? '').trim() !== '' && Number.isFinite(n) ? n : NaN; };

function readStores(rows) {
  const stores = [], problems = [];
  rows.forEach((r, i) => {
    const name = String(r.store ?? '').trim();
    if (!name && String(r.lat ?? '').trim() === '' && String(r.lon ?? '').trim() === '') return;
    const lat = num(r.lat), lon = num(r.lon);
    if (!name || !(lat >= -90 && lat <= 90) || !(lon >= -180 && lon <= 180)) { problems.push('row ' + (i + 2) + ' (' + (name || '?') + '): needs store, lat and lon'); return; }
    stores.push({ name, lat, lon, notes: String(r.notes ?? '').trim(), contact: String(r.contact ?? '').trim() });
  });
  return { stores, problems };
}

// one fact per flagged day: what the forecast says and which rule it hit
function weatherFacts(store, forecast, cfg) {
  const d = forecast?.daily ?? {};
  const facts = [];
  (d.time ?? []).forEach((date, i) => {
    const v = { date, max_c: d.temperature_2m_max?.[i], min_c: d.temperature_2m_min?.[i], rain_probability_pct: d.precipitation_probability_max?.[i], rain_mm: d.precipitation_sum?.[i] };
    const events = [];
    if (v.rain_probability_pct >= Number(cfg.rain_probability_pct)) events.push('rain');
    if (v.rain_mm >= Number(cfg.heavy_rain_mm)) events.push('heavy_rain');
    if (v.max_c >= Number(cfg.hot_c)) events.push('hot');
    if (v.min_c <= Number(cfg.cold_c)) events.push('cold');
    if (events.length) facts.push({ id: 'F' + (facts.length + 1), store: store.name, events, values: v });
  });
  return facts;
}

// numbers a sentence may use: the forecast values only. Dates are allowed only in a date shape (10月17日, 10/17, 17日)
// and are removed before the check, so "10% off" cannot hide behind the month 10.
function numbersOf(facts) {
  const s = new Set();
  for (const f of facts) for (const [k, v] of Object.entries(f.values)) {
    if (k === 'date') continue;
    if (typeof v === 'number' && Number.isFinite(v)) { s.add(String(v)); s.add(String(Math.round(v))); s.add(String(Math.round(v * 10) / 10)); }
  }
  return s;
}
function stripDates(text, facts) {
  const md = new Set(), days = new Set(), years = new Set();
  for (const f of facts) { const [y, m, d] = String(f.values.date).split('-').map(Number); md.add(m + '/' + d); days.add(d); years.add(y); }
  return nfkc(text)
    .replace(/(\d{4})\s*年/g, (all, y) => (years.has(Number(y)) ? ' ' : all))
    // a range: 10月16～18日, 10/16-18
    .replace(/(\d{1,2})\s*[月\/]\s*(\d{1,2})\s*日?\s*[〜～~\-–]\s*(\d{1,2})\s*日?/g, (all, m, a, b) => (md.has(Number(m) + '/' + Number(a)) && md.has(Number(m) + '/' + Number(b)) ? ' ' : all))
    .replace(/(\d{1,2})\s*月\s*(\d{1,2})\s*日/g, (all, m, d) => (md.has(Number(m) + '/' + Number(d)) ? ' ' : all))
    .replace(/(\d{1,2})\/(\d{1,2})(?!\d)/g, (all, m, d) => (md.has(Number(m) + '/' + Number(d)) ? ' ' : all))
    .replace(/(\d{1,2})\s*日/g, (all, d) => (days.has(Number(d)) ? ' ' : all))
    .replace(/\d{4}-\d{2}-\d{2}/g, (all) => (facts.some((f) => f.values.date === all) ? ' ' : all));
}

function checkTexts(raw, facts, cfg) {
  let ai = null;
  try {
    const t = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const a = t.indexOf('{'), z = t.lastIndexOf('}');
    ai = JSON.parse(a >= 0 && z > a ? t.slice(a, z + 1) : t);
  } catch (e) { ai = null; }
  if (!ai) return { ok: false, problem: 'the AI output could not be read as JSON', memo: [], message: null };
  const byId = new Map(facts.map((f) => [f.id, f]));
  const ng = String(cfg.ng_words ?? '').split(/[,、]\s*/).map((w) => w.trim()).filter(Boolean);
  const check = (text, ids, isMessage) => {
    const problems = [];
    const used = (Array.isArray(ids) ? ids : []).map(String).filter((id) => byId.has(id)).map((id) => byId.get(id));
    if (!String(text ?? '').trim()) problems.push('empty');
    if (!used.length) problems.push('no fact referenced');
    const allowed = numbersOf(used);
    const bad = [...new Set(stripDates(text, used).match(/\d+(?:\.\d+)?/g) ?? [])].filter((n) => !allowed.has(n) && !allowed.has(String(Number(n))));
    if (bad.length) problems.push('numbers not in the forecast: ' + bad.join(', '));
    if (isMessage) {
      const len = [...nfkc(text)].length;
      if (len > Number(cfg.max_message_chars)) problems.push('too long: ' + len + ' characters (limit ' + cfg.max_message_chars + ')');
      const hit = ng.filter((w) => nfkc(text).includes(nfkc(w)));
      if (hit.length) problems.push('words you do not use: ' + hit.join(', '));
    }
    return { text: String(text ?? '').trim(), ok: problems.length === 0, problems: problems.join('; ') };
  };
  const memo = (Array.isArray(ai.staff_memo) ? ai.staff_memo : []).slice(0, 5).map((m) => check(m?.text, m?.fact_ids, false));
  const message = ai.customer_message ? check(ai.customer_message.text, ai.customer_message.fact_ids, true) : null;
  return { ok: true, problem: '', memo, message };
}

const LABEL = { rain: { ja: '雨', en: 'rain' }, heavy_rain: { ja: '大雨', en: 'heavy rain' }, hot: { ja: '暑さ', en: 'heat' }, cold: { ja: '寒さ', en: 'cold' } };
function slackText(store, facts, checked, cfg) {
  const ja = String(cfg.language || 'en').toLowerCase().startsWith('ja');
  const L = (e) => LABEL[e][ja ? 'ja' : 'en'];
  const rows = facts.map((f) => '• ' + f.values.date + ' [' + f.events.map(L).join(', ') + '] ' + (ja ? '最高' : 'max ') + f.values.max_c + '°C / ' + (ja ? '最低' : 'min ') + f.values.min_c + '°C / ' + (ja ? '降水確率' : 'rain ') + f.values.rain_probability_pct + '% / ' + f.values.rain_mm + ' mm').join('\n');
  const mark = (x) => (x.ok ? '✓ ' : ':warning: ') + x.text + (x.ok ? '' : '  _(' + x.problems + ')_');
  const out = [(ja ? ':sun_behind_rain_cloud: *天気の準備* ' : ':sun_behind_rain_cloud: *Weather ahead* ') + store.name + (store.contact ? ' ' + (/^[UW][A-Z0-9]{6,}$/.test(store.contact) ? '<@' + store.contact + '>' : store.contact) : ''),
    (ja ? '*予報（Open-Meteo、コードが判定）*\n' : '*Forecast (Open-Meteo, flagged by code)*\n') + rows];
  if (!checked.ok) out.push(':warning: ' + checked.problem);
  else {
    if (checked.memo.length) out.push((ja ? '*スタッフ向けの準備（AI、コードが照合）*\n' : '*Prep for the staff (AI, checked by code)*\n') + checked.memo.map(mark).join('\n'));
    if (checked.message) out.push((ja ? '*お客様向けの文の案（使う前に読んでください）*\n' : '*Draft for customers (read before you use it)*\n') + mark(checked.message));
  }
  out.push(ja ? '_予報は外れることがあります。前もって動くための目安です。_' : '_Forecasts can be wrong. This is a heads-up, not a promise._');
  return out.join('\n');
}

const { stores, problems } = readStores($input.all().map((i) => i.json));
if (problems.length) throw new Error('Fix the Stores tab: ' + problems.join('; '));
if (!stores.length) throw new Error('The Stores tab has no store yet (columns: store, lat, lon, notes, contact).');
return stores.map((s) => ({ json: s }));

